using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;
// Reads only the known string-to-string option map; unknown save formats fail closed.
public sealed class ArcPreferences {
 public readonly Dictionary<string,string> Values=new Dictionary<string,string>(StringComparer.Ordinal);
 readonly Dictionary<string,byte[]> entries=new Dictionary<string,byte[]>();byte[] bytes;int sizeOffset,start,end;
 static string Read(BinaryReader r){int n=r.ReadInt32();if(n==0)return "";if(n<1||n>65536||r.BaseStream.Position+n>r.BaseStream.Length)throw new IOException("Unsupported option string format.");byte[] b=r.ReadBytes(n);if(b[n-1]!=0)throw new IOException("Invalid option string.");return Encoding.UTF8.GetString(b,0,n-1);}
 static void Put(BinaryWriter w,string s){byte[] b=Encoding.UTF8.GetBytes(s);w.Write(b.Length+1);w.Write(b);w.Write((byte)0);}
 public static bool Allowed(string key){return key.IndexOf("Consent",StringComparison.OrdinalIgnoreCase)<0&&new[]{"GameplayOption.Audio.","GameplayOption.Display.","GameplayOption.Scalability.","GameplayOption.Graphics.","GameplayOption.Controls.","GameplayOption.Accessibility.","GameplayOption.Gameplay.","GameplayOption.Interface.","GameplayOption.Crosshair.","GameplayOption.CameraGadget.","GameplayOption.UI.GamepadTooltips","GameplayOption.UI.ExpeditionStats","GameplayOption.ShowInputOverlay","GameplayOption.ShowNavigation"}.Any(p=>key.StartsWith(p,StringComparison.Ordinal));}
 public static ArcPreferences Parse(byte[] bytes){
  if(bytes.Length<128||bytes.Length>262144||Encoding.ASCII.GetString(bytes,0,4)!="GVAS"||Encoding.ASCII.GetString(bytes).IndexOf("EmbarkOptionSaveGameV1",StringComparison.Ordinal)<0)throw new IOException("Unsupported ARC settings file. No changes made.");
  var result=new ArcPreferences{bytes=bytes};byte[] marker=Encoding.ASCII.GetBytes("Properties\0");int at=-1;for(int i=4;i<bytes.Length-marker.Length;i++){bool match=true;for(int j=0;j<marker.Length;j++)if(bytes[i+j]!=marker[j]){match=false;break;}if(match&&BitConverter.ToInt32(bytes,i-4)==marker.Length){if(at!=-1)throw new IOException("Ambiguous ARC settings map.");at=i-4;}}
  if(at<0)throw new IOException("ARC settings map not found.");using(var r=new BinaryReader(new MemoryStream(bytes))){r.BaseStream.Position=at;if(Read(r)!="Properties"||Read(r)!="MapProperty"||r.ReadInt32()!=2||Read(r)!="NameProperty"||r.ReadInt32()!=0||Read(r)!="StrProperty"||r.ReadInt32()!=0)throw new IOException("ARC settings format changed.");result.sizeOffset=(int)r.BaseStream.Position;int size=r.ReadInt32();if(r.ReadInt32()!=0||r.ReadByte()!=0)throw new IOException("Unsupported ARC map flags.");result.start=(int)r.BaseStream.Position;int count=r.ReadInt32();if(count<1||count>2048)throw new IOException("Invalid ARC option count.");for(int i=0;i<count;i++){int pairStart=(int)r.BaseStream.Position;string key=Read(r),value=Read(r);if(result.Values.ContainsKey(key))throw new IOException("Duplicate ARC option.");result.Values.Add(key,value);result.entries.Add(key,bytes.Skip(pairStart).Take((int)r.BaseStream.Position-pairStart).ToArray());}result.end=(int)r.BaseStream.Position;if(size!=result.end-result.start+4)throw new IOException("ARC map length changed.");}
  return result;
 }
 public byte[] Merge(Dictionary<string,string> selected){foreach(var item in selected){if(!Allowed(item.Key)||item.Value==null||item.Value.Length>8192)throw new IOException("Unsupported ARC preference.");}byte[] map;using(var m=new MemoryStream()){using(var w=new BinaryWriter(m,Encoding.UTF8,true)){w.Write(Values.Count+selected.Keys.Count(k=>!Values.ContainsKey(k)));foreach(var item in Values){if(selected.ContainsKey(item.Key)){Put(w,item.Key);Put(w,selected[item.Key]);}else w.Write(entries[item.Key]);}foreach(var item in selected.Where(p=>!Values.ContainsKey(p.Key))){Put(w,item.Key);Put(w,item.Value);}}map=m.ToArray();}using(var output=new MemoryStream()){output.Write(bytes,0,start);output.Write(map,0,map.Length);output.Write(bytes,end,bytes.Length-end);byte[] merged=output.ToArray();Buffer.BlockCopy(BitConverter.GetBytes(map.Length+4),0,merged,sizeOffset,4);var check=Parse(merged);foreach(var item in selected)if(check.Values[item.Key]!=item.Value)throw new IOException("ARC preference verification failed.");return merged;}}
 public static readonly HashSet<string> IniSections=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"Internationalization","ScalabilityGroups","/Script/Engine.GameUserSettings","/Script/EmbarkUserSettings.EmbarkGameUserSettings","D3DRHIPreference"};
 public static string SelectIni(string text,bool chosen){string section="";var output=new StringBuilder();foreach(string line in text.Replace("\r","").Split('\n')){string trim=line.Trim();if(trim.StartsWith("[")&&trim.EndsWith("]"))section=trim.Substring(1,trim.Length-2);if(IniSections.Contains(section)==chosen)output.AppendLine(line);}return output.ToString();}
}
